import json
import pandas as pd

MAP = {
    "user_id": "user_id", "id": "user_id", "userId": "user_id",
    "email": "email", "email_address": "email",
    "full_name": "name", "name": "name", "userName": "name",
    "registration_date": "created_date", "created_at": "created_date", "joined": "created_date",
    "status": "status", "is_active": "status", "active": "status",
}
FIELDS = ["name", "email", "created_date", "status"]

def norm_date(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    try:
        return pd.to_datetime(str(v)).strftime("%Y-%m-%d")
    except Exception:
        return str(v)

def norm_status(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    if isinstance(v, bool):
        return "active" if v else "inactive"
    s = str(v).strip().lower()
    if s in ("true", "1", "yes"):
        return "active"
    if s in ("false", "0", "no"):
        return "inactive"
    return str(v)

def load(df):
    df = df.rename(columns={c: MAP[c] for c in df.columns if c in MAP})
    recs = {}
    for r in df.to_dict("records"):
        uid = int(r["user_id"])
        rec = {}
        for f in FIELDS:
            v = r.get(f)
            if f == "created_date":
                v = norm_date(v)
            elif f == "status":
                v = norm_status(v)
            elif v is not None and not (isinstance(v, float) and pd.isna(v)):
                v = str(v).strip()
            else:
                v = None
            rec[f] = v
        recs[uid] = rec
    return recs

with open("/data/source_a/users.json") as fh:
    a = json.load(fh)
if isinstance(a, dict):
    a = next(v for v in a.values() if isinstance(v, list))
sources = {
    "source_a": load(pd.DataFrame(a)),
    "source_b": load(pd.read_csv("/data/source_b/users.csv", dtype=str, keep_default_na=False).replace("", None)),
    "source_c": load(pd.read_parquet("/data/source_c/users.parquet")),
}

all_ids = sorted(set().union(*[s.keys() for s in sources.values()]))
rows, conflicts = [], []
for uid in all_ids:
    row = {"user_id": uid}
    for f in FIELDS:
        vals = {src: recs[uid][f] for src, recs in sources.items() if uid in recs and recs[uid][f] is not None}
        selected = next(iter(vals.values()), None)
        row[f] = selected
        if len(set(vals.values())) > 1:
            conflicts.append({"user_id": uid, "field": f, "values": vals, "selected": selected})
    rows.append(row)

out = pd.DataFrame(rows, columns=["user_id"] + FIELDS)
out["user_id"] = out["user_id"].astype("int64")
for f in FIELDS:
    out[f] = out[f].astype(object)
out.to_parquet("/app/merged_users.parquet", index=False)
with open("/app/conflicts.json", "w") as fh:
    json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, fh, indent=2)
EOF
